    (* MV-FC-HS-4750: hand-switch driven fail-closed valve *)
    IF HS_4750_01 THEN
        MV_FC_HS_4750_Pct := 100.0;
    ELSE
        MV_FC_HS_4750_Pct := 0.0;
    END_IF;
    MV_FC_HS_4750_Out       := REAL_TO_INT(6554.0 + (MV_FC_HS_4750_Pct / 100.0) * (32767.0 - 6554.0));

    (* Auxiliary valves — hold at 50% nominal until dedicated loops are defined *)
    SV_104_01_Out           := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    MV_H_1007_N1_INLET_Out  := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    MV_H_1007_N4_OUTLET_Out := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    CV_66KL21_80_Out        := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    BV_73KH12_25_1_Out      := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    BV_73KH12_25_2_Out      := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    BV_73KH12_50_1_Out      := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    BV_73KH12_50_2_Out      := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    BV_MNc_47125_1_Out      := REAL_TO_INT(6554.0 + (50.0 / 100.0) * (32767.0 - 6554.0));
    XV_75SA21_80            := HS_4750_01;
ELSE
    TV_4750_03_Out          := 32767;
    PVA_4712_02_Out         := 6554;
    SV_104_01_Out           := 6554;
    MV_FC_HS_4750_Out       := 6554;
    MV_H_1007_N1_INLET_Out  := 6554;
    MV_H_1007_N4_OUTLET_Out := 6554;
    CV_66KL21_80_Out        := 6554;
    BV_73KH12_25_1_Out      := 6554;
    BV_73KH12_25_2_Out      := 6554;
    BV_73KH12_50_1_Out      := 6554;
    BV_73KH12_50_2_Out      := 6554;
    BV_MNc_47125_1_Out      := 6554;
    XV_75SA21_80            := FALSE;
END_IF;

System_Alarm :=
    PI_4712_01_HH_Active OR PI_4712_01_LL_Active OR
    PI_4712_01_H         OR PI_4712_01_L          OR
    LOOP_4750_03_TRIP    OR LOOP_4712_02_TRIP      OR
    LOOP_104_01_TRIP     OR SAFE_STATE;

END_PROGRAM
